-- 05-capacity.sql
--
-- EXTRACTED VERBATIM from artifacts/v1/gaos-arcadedb-model.html, which is the
-- source of truth for this schema. Do not edit this file to change the model:
-- change the document, then re-extract. A deviation that lives only here is a
-- schema nobody reviewing the model document would ever see.
--
-- Applied in filename order by deploy/schema/apply.sh. Every statement carries
-- IF NOT EXISTS, so applying twice is a no-op rather than an error.

CREATE VERTEX TYPE Agent IF NOT EXISTS EXTENDS GaosVertex;
CREATE PROPERTY Agent.name             STRING  (mandatory true, notnull true);
CREATE PROPERTY Agent.role             STRING  (mandatory true, notnull true,
                 regexp 'planner|architect|backend|frontend|qa|security|devops');
CREATE PROPERTY Agent.model            STRING  (notnull true);
CREATE PROPERTY Agent.availability     STRING  (default 'IDLE',
                 regexp 'IDLE|RESERVED|BUSY|IN_MEETING|COOLDOWN|OFFLINE');
CREATE PROPERTY Agent.capacity         INTEGER (default 1, min 1, max 8);
CREATE PROPERTY Agent.reliabilityScore FLOAT   (default 0.5, min 0, max 1);
CREATE PROPERTY Agent.costScore        FLOAT   (default 0.5, min 0, max 1);
CREATE PROPERTY Agent.allowedTools     LIST;

CREATE VERTEX TYPE Room IF NOT EXISTS EXTENDS GaosVertex;
CREATE PROPERTY Room.name     STRING  (mandatory true, notnull true);
CREATE PROPERTY Room.kind     STRING  (regexp 'architecture|backend|qa|release|knowledge|meeting');
CREATE PROPERTY Room.capacity INTEGER (default 3, min 1);

CREATE VERTEX TYPE CalendarSlot IF NOT EXISTS EXTENDS GaosVertex;
CREATE PROPERTY CalendarSlot.kind     STRING (mandatory true, notnull true,
                 regexp 'focus|meeting|review|cooldown|milestone');
CREATE PROPERTY CalendarSlot.startsAt DATETIME (mandatory true, notnull true);
CREATE PROPERTY CalendarSlot.endsAt   DATETIME (mandatory true, notnull true);
CREATE PROPERTY CalendarSlot.reason   STRING;
